  queue_phase_finalizing: "Finalizing on PS5",
  queue_phase_finalizing_hint: "Все байты уже на PS5; она фиксирует индекс файлов. При большом количестве файлов (10 000+) это обычно занимает много минут — не закрывайте приложение.",
  upload_status_finalizing: "Finalizing on PS5",
  upload_status_finalizing_hint: "PS5 фиксирует индекс файлов. При большом количестве файлов это может занять время — не закрывайте приложение.",
