  upload_eta_resume_hint: "Для папок такого размера режим «Продолжить» (пропуск файлов, уже имеющихся на PS5) экономит час и более при повторных загрузках. Выбор появится при нажатии «Загрузить».",
  activity_phase_finalizing_with_counter: "Завершение на PS5 — {done} / {total} файлов",
