installed_smp_off_body: "Образы дисков монтируются из /mnt/shadowmnt с помощью ShadowMount+. Похоже, он не запущен, поэтому эти игры не смонтируются и не запустятся. Отправьте его на консоль, подождите несколько секунд, затем Обновить.",
