// Editing a game image in place (ShadowMount+ checkout)
library_edit_files_tooltip: "Изъять этот образ из ShadowMount+ и смонтировать его для записи, чтобы добавлять или заменять файлы внутри",
library_edit_modal_run: "Изъять для редактирования",
library_edit_confirm_title: "Изменить этот образ игры?",
library_edit_confirm_body: "{name} будет перемещён из папки ShadowMount+ и смонтирован для записи в {mountPoint}.\n\nПока идёт редактирование, игра исчезает с главного экрана PS5. Она вернётся, когда вы завершите сеанс редактирования.\n\nИзменение не того файла внутри образа игры может помешать её запуску, и отменить это нельзя. Если не уверены, сделайте резервную копию.",
library_edit_confirm_ok: "Изъять для редактирования",
library_edit_needs_mount_point: "Для редактирования нужна явно заданная точка монтирования. Обновите помощник PS5 до версии, которая позволяет её выбрать.",
notif_library_edit_failed: "Не удалось изъять для редактирования",
edit_session_title: "Редактирование {name}",
edit_session_body: "Пока сеанс открыт, игра скрыта с главного экрана PS5 — ShadowMount+ не видит образ там, где он сейчас находится. Завершите редактирование, чтобы вернуть его на место.",
edit_session_open: "Открыть файлы",
edit_session_finish: "Завершить редактирование",
edit_session_done: "Сеанс редактирования завершён",
edit_session_done_body: "{name} вернулся в исходную папку. ShadowMount+ смонтирует и зарегистрирует его снова примерно через минуту.",


