installed_launch_smp_refused: "PS5 отказалась запускать эту игру (0x80940033), хотя kstuff работает. ShadowMount+ монтирует игру при её запуске, а этого не произошло. Закройте запущенную игру, отправьте ShadowMount+ заново из раздела Payloads и нажмите «Играть».",
connection_mac_local_network_hint: "Возможно, macOS блокирует доступ этого приложения к локальной сети. Откройте «Системные настройки» → «Конфиденциальность и безопасность» → «Локальная сеть», разрешите PS5Upload и проверьте снова.",
batch_space_tight: "{drive}: {size} могут не поместиться. При записи PS5 удерживает примерно на пятую часть больше, поэтому поместится, скорее всего, около {fits}. Попробовать всё равно можно.",
