remotePlay_np_title: "Включить собственную настройку дистанционного воспроизведения PS5",
remotePlay_np_body: "PS5 позволяет включить дистанционное воспроизведение только для учётной записи, вошедшей в PlayStation Network. np-fake-signin {version} заставляет консоль считать вашу учётную запись вошедшей без настоящего входа в PSN. После его запуска переключатель в Settings → System → Remote Play можно включить.",
