health_junk_explain_v2: "То, что создал ps5upload и что больше не нужно: незавершённые файлы прерванных передач, копии пакетов, пролежавшие во временной папке больше часа, и старые файлы теста скорости. Просматриваются только собственные папки ps5upload; ваши игры, пакеты и сохранения не затрагиваются никогда.",
