trace_what: "Для LZ4-образа, который загружается так, как игра играет. Измерительная сборка ampr_emu записывает каждый файл, который игра читает во время игры; профиль, построенный по этим сессиям, выбирает размеры блоков, раскладку и кэши для каждого файла вместо одной догадки для всех. Convert использует его при создании LZ4-образа этой игры.",
trace_playing_hint: "Измерение на {name}: запустите игру, загрузите сохранение, пройдите несколько зон, затем выйдите с консоли. Каждая сессия записывается, когда игра закрывается при открытой странице, или кнопкой «Записать сессию».",
trace_no_sessions: "Игровых сессий пока не записано.",
trace_sessions: "Записано сессий: {n} ({size} чтений).",
trace_profile: "Профиль построен {date} по {n} сессиям: упаковано файлов {files}, декодированный кэш {cache}, воркеров {workers}. Convert использует его для LZ4-образа этой игры.",
trace_needs_folder: "Нужна игра в виде папки на подключённой консоли.",
trace_start: "Начать измерение",
trace_quit_first: "Сначала выйдите из игры: сессия записывается при закрытии.",
trace_collect: "Записать сессию",
