"collection.copy_link_hint_v2": "Ссылка, по которой эта PS5 может сама установить пакет (браузер или установщик пакетов на консоли). Работает, пока этот компьютер включён, пока вы не остановите её в разделе «Раздаётся» или не закроете приложение.",
