"collection.serving_body_v2": "Пакеты, которые этот компьютер раздаёт PS5, забирающей их сама. Ссылка работает для PS5, для которой создана (или для любого устройства в вашей сети, если разрешить), пока вы её не остановите или не закроете приложение.",
