hw_fan_preset_cool_hint: "Держит консоль холоднее; вентиляторы работают громче",
hw_fan_preset_quiet_hint_v2: "Вентиляторы тише; консоль работает теплее",
ps5notif_empty_hint_v2: "Когда ps5upload выводит сообщение на ваш телевизор, например PIN Remote Play или включение чита, оно появляется здесь, чтобы его можно было прочитать снова. Это не собственная панель уведомлений PS5; консоль не позволяет её читать.",
remotePlay_check_account_hint_v2: "Эта учётная запись ни разу не активировалась, поэтому не может выполнить сопряжение. «Профиль» может активировать её, назначив ID учётной записи; это меняет данные учётной записи, и сохранения, созданные после этого, привязываются к этому ID.",
