"fpkg.image.lz4_install_runtime_body": "{reason}. В образ кладётся ampr_emu 0.4.2.1 от drakmor как fakelib/libSceAmpr.sprx (загружается один раз из релиза на GitHub и сверяется с известным хешем); собственная копия игры остаётся рядом как libSceAmpr.sprx.orig.",
"fpkg.image.lz4_no_ampr": "Эта игра не читает файлы через AMPR, поэтому ничто в ней не может отдавать паки. Сожмите её в .ffpfsc: ShadowMount+ распаковывает его для любой игры.",
"fpkg.image.verify_chunk": "Контрольное чтение, за один раз",
