"fakegame.fw.body": "Установка пройдёт, но фейковые игровые пакеты PS5 нельзя запустить на прошивке выше {last}. Пакеты PS4 работают, а homebrew-приложения PS5 запускаются как обычно.",
"fakegame.fw.launch": "Фейковые игровые пакеты PS5 нельзя запустить на прошивке выше {last} (на этой консоли {fw}). Если эта игра установлена из фейкового пакета, поэтому она и не запускается. Пакеты PS4 работают.",
